module uart_ten(
	sys_clk,
	rst_n,
	data_ID,
	data_angle,
	data_time,
	start,
	uart_ten_busy,
	u_txd,
	uart_en,
	data_send,
	send_busy);

	//---Ports declearation: generated by Robei---
	input sys_clk;
	input rst_n;
	input [7:0] data_ID;
	input [15:0] data_angle;
	input [15:0] data_time;
	input start;
	output uart_ten_busy;
	output u_txd;
	output uart_en;
	output [7:0] data_send;
	input send_busy;

	wire sys_clk;
	wire rst_n;
	wire [7:0] data_ID;
	wire [15:0] data_angle;
	wire [15:0] data_time;
	wire start;
	reg uart_ten_busy;
	wire u_txd;
	reg uart_en;
	reg [7:0] data_send;
	wire send_busy;

	//----Code starts here: integrated by Robei-----
		
	
	
		parameter  DATA_H1=8'h55,
		               		DATA_H2=8'h55,
		               		DATA_LTH=8'h07,
		               		DATA_CMD=8'h01;
		parameter  IDLE=4'd0;
		parameter  START=4'd1;
		parameter  FINISH=4'd2;
		          
		           
		wire cnt_byte_sim;
		wire [2:0] state_sim;
		wire [3:0] cnt_data_sim;
		wire [7:0] data_send_sim;
		wire ut_en_sim;
		wire [3:0]u_state_sim;     
		 wire [7:0]data_h1;
		 wire [7:0]data_h2;
		 wire [7:0]data_id;
		 wire [7:0]data_lth;
		 wire [7:0]data_cmd;
		 wire [7:0]data_pm1;
		 wire [7:0]data_pm2;
		 
		 wire [7:0]data_pm3;
		 wire [7:0]data_pm4;
		 wire [7:0] data_che;
		 
		// wire sart;                   
		 reg start_en;                 
		 reg [9:0]cnt_finish;
		 reg [3:0] cnt_byte;
		 
		 reg [8:0] cnt_delay;
		 reg delay_finish;
		
		 reg [3:0] state;
		 reg [3:0] next_state;
		 
		 
		assign data_h1=DATA_H1 ;
		assign data_h2=DATA_H2 ;
		assign data_id=data_ID ;
		
		assign data_lth=DATA_LTH;
		assign data_cmd=DATA_CMD;
		assign data_pm1=data_angle[7:0];
		assign data_pm2=data_angle[15:8];
		assign data_pm3=data_time[7:0];
		assign data_pm4=data_time[15:8];
		assign data_che=~(data_id+data_lth+data_cmd+data_pm1+data_pm2+data_pm3+data_pm4);
		
		
		//pos or neg
		
		reg  send_busy_r;
		wire sd_pos;
		wire sd_neg;
		
		//reg uart_ten_busy;           
		assign sd_pos=send_busy&&~send_busy_r;
		assign sd_neg=~send_busy&&send_busy_r;
		always@(posedge sys_clk or negedge rst_n)begin
		    if(!rst_n)
		        send_busy_r<=1'b0;
		    else
		        send_busy_r<=send_busy;
		end
		
		//cnt_byte
		assign cnt_byte_sim=cnt_byte;    
		always @(posedge sys_clk or negedge rst_n)begin
		    if(!rst_n)
		        cnt_byte<=4'b0000;
		    else if(sd_neg)        
		            cnt_byte<=cnt_byte+1;
		    else if(state==FINISH)
		         cnt_byte<=4'b0000;
		    else
		        cnt_byte<=cnt_byte;           
		end
		
		//data_send
		assign data_send_sim=data_send;
		always@(posedge sys_clk or negedge rst_n)begin
		    if(!rst_n)
		        data_send<=8'b0000_0000;
		    else
		        case (cnt_byte)
		            4'd0:   data_send<= data_h1;
		            4'd1:   data_send<= data_h2;
		            4'd2:   data_send<= data_id;
		            4'd3:   data_send<= data_lth;
		            4'd4:   data_send<= data_cmd;
		            4'd5:   data_send<= data_pm1;
		            4'd6:   data_send<= data_pm2;
		            4'd7:   data_send<= data_pm3;
		            4'd8:   data_send<= data_pm4;
		            4'd9:   data_send<= data_che;
		            default: data_send<=data_h1;   
		        endcase
		        
		end
		//delay
		always@(posedge sys_clk or negedge rst_n)begin
		    if(!rst_n)begin
		        delay_finish<=1'b0;
		        cnt_delay<=4'b0000;
		     end   
		    else if(~send_busy&&start_en)         
		        if(cnt_delay<8'd100)
		            cnt_delay<=cnt_delay+1;
		        else begin
		            if(cnt_byte<4'd10)begin    
		                delay_finish<=1'b1;
		                cnt_delay<=4'b0000;
		            end
		            else begin
		                delay_finish<=1'b0;
		                cnt_delay<=4'b0000;
		            end
		        end
		    else begin
		        delay_finish<=1'b0;
		        cnt_delay<=4'b0000;
		    end        
		end
		assign ut_en_sim=uart_en;  
		assign u_state_sim=state;
		always @(posedge sys_clk or negedge rst_n)begin
		    if(!rst_n)
		        state<=4'b0000;
		    else
		        state<=next_state;
		end
		always @(*)begin
		    if(!rst_n)
		        next_state<=4'b0000;
		    else 
		        case(state)
		            IDLE:begin
		                if(start)
		                    next_state=START;
		                else
		                    next_state=IDLE;
		            end
		            START:begin
		                if(cnt_byte==4'd10&&cnt_delay==8'd100)
		                    next_state= FINISH;
		                else
		                    next_state=START;
		            end
		            FINISH:begin
		               if(cnt_finish==10'd100)
		                  next_state=IDLE;
		               else
		                  next_state=FINISH;
		            end
		            default:    ;
		          endcase
		end
		always @(posedge sys_clk or negedge rst_n)begin
		    if(!rst_n)begin
		        uart_en<=1'b0;
		        uart_ten_busy<=1'b0;
		        cnt_finish<=10'd0;
		        start_en<=1'b0;
		    end
		    else
		        case(state)
		            IDLE:begin
		                uart_en<=1'b0;
		                uart_ten_busy<=1'b0;
		                cnt_finish<=10'd0;
		                start_en<=1'b0;
		            end
		            START:begin
		                uart_ten_busy<=1'b1;
		                start_en<=1'b1;
		                if(sd_pos)
		                    uart_en<=1'b0;
		                else if(delay_finish)           
		                    uart_en<=1'b1;
		                else if(cnt_byte==4'd10)       
		                    uart_en<=1'b0;
		                else
		                    uart_en<=uart_en;
		            end
		            FINISH:begin
		                start_en<=1'b0;
		                cnt_finish<=cnt_finish+1;
		                if(cnt_finish==10'd90)
		                    uart_ten_busy<=1'b0;
		            end
		            default:    ;
		        endcase
		end
	
	
	
	//---Module instantiation---
	Uart_txd Uart_txd1(
		.sys_clk(sys_clk),
		.rst_n(rst_n),
		.uart_en(uart_en),
		.data_send(data_send),
		.send_busy(send_busy),
		.uart_txd(u_txd));

endmodule    //uart_ten

